package main

import (
	"fmt"
	"sort"
	"strings"
)

// TypeScript: interfaces whose property names are the schemas' JSON names, so
// documents parsed with JSON.parse are used as-is. Schema integers (counts,
// batch numbers) are `number`: they are bounded far below 2^53. int64 and
// decimal *values* are strings in the schemas and stay strings.

func tsHeader(source string) string {
	return "// <auto-generated>\n" +
		"//   Generated by tools/codegen from " + source + ". DO NOT EDIT.\n" +
		"//   Regenerate with: go -C tools/codegen run . -repo ../.. (from the repository root).\n" +
		"// </auto-generated>\n"
}

func (m *Model) tsType(t TypeRef) string {
	var s string
	switch t.Kind {
	case KString:
		s = "string"
	case KInt, KFloat:
		s = "number"
	case KBool:
		s = "boolean"
	case KJSON:
		return "unknown"
	case KObject:
		s = m.names[t.Class]
	case KList:
		elem := m.tsType(*t.Elem)
		if strings.Contains(elem, " ") {
			elem = "(" + elem + ")"
		}
		s = elem + "[]"
	}
	if t.Nullable {
		s += " | null"
	}
	return s
}

func tsDoc(indent, doc string) string {
	if doc == "" {
		return ""
	}
	lines := wrap(strings.ReplaceAll(doc, "*/", "* /"), 90)
	if len(lines) == 1 {
		return indent + "/** " + lines[0] + " */\n"
	}
	var b strings.Builder
	b.WriteString(indent + "/**\n")
	for _, l := range lines {
		b.WriteString(indent + " * " + l + "\n")
	}
	b.WriteString(indent + " */\n")
	return b.String()
}

func (m *Model) emitTypeScript(codes []ErrorCode) (map[string]string, error) {
	classes := make([]*Class, 0, len(m.order))
	for _, key := range m.order {
		classes = append(classes, m.classes[key])
	}
	sort.SliceStable(classes, func(i, j int) bool { return classes[i].Name < classes[j].Name })

	var b strings.Builder
	b.WriteString(tsHeader("specs/*.schema.json"))
	b.WriteString("/* eslint-disable */\n")
	for _, c := range classes {
		b.WriteString("\n")
		b.WriteString(tsDoc("", c.Doc))
		b.WriteString("export interface " + c.Name + " {\n")
		for _, f := range c.Fields {
			b.WriteString(tsDoc("  ", f.Doc))
			opt := "?"
			if f.Required {
				opt = ""
			}
			fmt.Fprintf(&b, "  %s%s: %s;\n", f.JSONName, opt, m.tsType(f.Type))
		}
		b.WriteString("}\n")
	}

	var e strings.Builder
	e.WriteString(tsHeader("specs/error-codes.json"))
	e.WriteString("/* eslint-disable */\n\n")
	e.WriteString("/** Severity of an error code. */\n")
	e.WriteString("export type ErrorSeverity = \"info\" | \"warning\" | \"error\" | \"fatal\";\n\n")
	e.WriteString("/** Definition of one stable error code. */\n")
	e.WriteString("export interface ErrorCodeInfo {\n  readonly code: string;\n  readonly title: string;\n  readonly severity: ErrorSeverity;\n  readonly retryable: boolean;\n  readonly meaning: string;\n  readonly remediation: string;\n}\n\n")
	e.WriteString("/** Stable error codes (specs/error-codes.json), for example `ErrorCodes.Map005`. */\n")
	e.WriteString("export const ErrorCodes = {\n")
	for _, c := range codes {
		fmt.Fprintf(&e, "  /** %s. */\n  %s: %q,\n", c.Title, errorConstName(c.Code), c.Code)
	}
	e.WriteString("} as const;\n\n")
	e.WriteString("/** Every defined code with its severity, retryability and remediation. */\n")
	e.WriteString("export const ErrorCodeInfos: Readonly<Record<string, ErrorCodeInfo>> = {\n")
	for _, c := range codes {
		fmt.Fprintf(&e, "  %q: { code: %q, title: %q, severity: %q, retryable: %t, meaning: %q, remediation: %q },\n",
			c.Code, c.Code, c.Title, c.Severity, c.Retryable, c.Meaning, c.Remediation)
	}
	e.WriteString("};\n")

	return map[string]string{
		"model.ts":      b.String(),
		"errorCodes.ts": e.String(),
	}, nil
}
